    "[id=22542] SourceFile=Linux_full.log Month=Jan Day=26 Time=17:23:29 Host=combo Component=named PID=2288 couldn't add command channel 127.0.0.1#953: not found",
    "[id=22543] SourceFile=Linux_full.log Month=Jan Day=26 Time=17:23:29 Host=combo Component=named PID=2288 couldn't add command channel ::1#953: not found"
  ],
  "context_events": [
    "[id=22534] SourceFile=Linux_full.log Month=Jan Day=26 Time=12:23:27 Host=combo Component=ntpd PID=2309 frequency initialized 0.000 PPM from /var/lib/ntp/drift",
    "[id=22544] SourceFile=Linux_full.log Month=Jan Day=26 Time=17:23:30 Host=combo Component=named PID=2288 running"
  ],
  "analysis": {
    "fault_category": "configuration",
    "affected_components": ["ntpd PID=2309", "named PID=2288"],
    "recovery_state": "unknown",
    "likely_cause": "ntpd did not recognize the authenticate directive; named reported that both command-channel endpoints were not found",
    "evidence_ids": ["22537", "22542", "22543"]
